const raw = $json.output?.[0]?.content?.[0]?.text || "";

// extract JSON
const match = raw.match(/\[.*\]/s);

if (!match) {
  return [{ json: { error: "No JSON found", raw_output: raw } }];
}

const jobs = JSON.parse(match[0]);

// 👇 THIS RETURNS ALL JOBS
return jobs.map(job => ({ json: job }));
